(function(root){
'use strict';
const groups={weapons:'Оружие',armor:'Броня',implants:'Киберимпланты',net:'Деки и базовые Черви',medicine:'Медикаменты',stims:'Стимуляторы',gadgets:'Гаджеты'};
const definitions=[['shooter','Стрелок','Точность и надёжность в перестрелке.','Detroiter','TargetLink'],['samurai','Уличный самурай','Ближний бой и выживание.','Kurogane Zero','PureAir','DermaSeal'],['shadow','Тень','Скрытное проникновение и разведка.','Whisper-9','Nightstalker','FGD Mole','DermaSeal'],['netrunner','Нетраннер','Дистанционный взлом и поддержка команды.','Third-Eye','Whisper-9','Blue-Soma','DermaSeal']];
const key=(cat,name)=>JSON.stringify([cat,name]);
function all(d){return Object.entries(d.catalog).flatMap(([cat,items])=>items.map(item=>({...item,cat,key:key(cat,item.name)})));}
function allowed(x){return !x.archived&&x.startAllowed===true&&Number.isSafeInteger(x.price)&&x.price>=0&&(x.cat!=='weapons'||typeof x.damage==='number'&&x.damage<=2)&&(x.cat!=='armor'||x.armor<=1)&&(x.cat!=='implants'||x.slots===1)&&(x.cat!=='programs'||x.type==='Базовый червь')&&x.cat!=='perks';}
function kits(d){const items=all(d);return definitions.map(([id,name,description,...parts])=>{parts.push('Легкая');const rows=parts.map(p=>items.find(x=>x.name.includes(p)&&allowed(x)));return {id,name,description,rows:rows.filter(Boolean),ready:rows.every(Boolean),price:rows.reduce((n,x)=>n+(x?.price||0),0)};});}
function quote(s,d,complete=false){const items=all(d),rows=[];let total=0;for(const [id,n] of Object.entries(s.items||{})){if(!Number.isSafeInteger(n)||n<1)throw Error('Некорректное количество');const x=items.find(x=>x.key===id);if(!x||!allowed(x))throw Error('Предмет недоступен на старте');if(x.cat!=='consumables'&&n!==1)throw Error('Этот предмет можно выбрать один раз');rows.push({...x,quantity:n});total+=x.price*n;}const deck=rows.some(x=>x.name.includes('Third-Eye')),free=s.free||[];if(new Set(free).size!==free.length||free.length>2)throw Error('Выбери двух различных Червей');if(free.length&&!deck)throw Error('Бесплатные программы требуют стартовую деку');for(const id of free){const x=items.find(x=>x.key===id);if(!x||!allowed(x)||x.cat!=='programs'||!rows.some(r=>r.key===id))throw Error('Недопустимый бесплатный Червь');total-=x.price;}if(total>2000)throw Error('Превышен бюджет 2 000 эдди');if(complete&&deck&&free.length!==2)throw Error('Выбери две различные бесплатные программы для деки');for(const [cat,max] of [['weapons',2],['armor',1],['implants',9],['programs',5],['consumables',6]])if(rows.filter(x=>x.cat===cat).length>max)throw Error('Недостаточно слотов в карточке');return {rows,total,left:2000-total,deck};}
function apply(c,s,d){const q=quote(s,d,true),r=JSON.parse(JSON.stringify(c));r.weapons=['',''];r.armor='';r.implants=Array.from({length:9},()=>({name:'',quality:''}));r.programs=Array(5).fill('');r.consumables=Array.from({length:6},()=>({name:'',quantity:''}));for(const cat of ['weapons','implants','programs','consumables'])q.rows.filter(x=>x.cat===cat).forEach((x,i)=>{r[cat][i]=cat==='implants'?{name:x.name,quality:'Стандарт'}:cat==='consumables'?{name:x.name,quantity:x.quantity}:x.name;});r.armor=q.rows.find(x=>x.cat==='armor')?.name||'';r.money=q.left;return r;}
root.ND_SHOP={all,allowed,kits,quote,apply,groups,key};if(typeof module!=='undefined')module.exports=root.ND_SHOP;
})(typeof window!=='undefined'?window:globalThis);
